import React, { useState, useEffect, useRef } from 'react'
import { CircleUserRound } from 'lucide-react'
import SignedInDrop from './SignedInDrop'
import "./Header.scss"

const useClickOutside = (ref, handler) => {
  useEffect(() => {
    const maybeHandler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        handler()
      }
    }

    document.addEventListener("mousedown", maybeHandler)

    return () => {
      document.removeEventListener("mousedown", maybeHandler)
    }
  }, [ref, handler])
}

const Header = () => {
  const [isOpen, setIsOpen] = useState(false)
  const [username, setUsername] = useState('Guest')
  const dropdownRef = useRef()

  const toggleDropdown = () => {
    setIsOpen(prev => !prev) // profile click reveals or hides dropdown
  }

  useClickOutside(dropdownRef, () => {
    setIsOpen(false)
  })

  return (
    <div className="header-container">
      <div className="header-section-container">
        <div className="profile-container">
          <CircleUserRound className="profile-icon" onClick={toggleDropdown} />
          {isOpen && (
            <SignedInDrop username={username} isOpen={isOpen} dropdownRef={dropdownRef} />
          )}
        </div>
      </div>
    </div>
  )
}

export default Header
